import os

from taf.rnc.oms.nwi3.pegasus_cli_wrapper import PegasusWrapper, get_file_content
from taf.rnc.oms.nwi3.sysconf_manager import OMSConfigManager


class nwi3(object):
    """
    Class for performing OMS (WCDMA core network element) operations, which mostly consist of parameters set and get.

    At the moment communication with OMS is provided via Pegasus Framework and Pegasus CLI commands thus Pegasus
    executable needs to be available on test machine in order to get methods work properly. Whole Pegasus project which
    consist of various test hierarchies is attached into the library, so user only need to provide the Pegasus SW under
    path /tmp/Pegasus (methods are calling /tmp/Pegasus/PegasusRCP)
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, pegasus_wrapper=PegasusWrapper()):
        self.pegasus_wrapper = pegasus_wrapper

    def setup_nwi3(self, rnc_number, oms_ip, oms_username='Nemuadmin', oms_password='nemuuser',
                   sysconf_path=os.path.join(os.path.dirname(__file__), 'pegasus_project/oms_conn_config.sc')):
        """
        Setup OMS configuration file in order to properly launch OMS management methods

        :param rnc_number: Number of RNC which will be accessed
        :type rnc_number: str
        :param oms_ip: IP of OMS which will be accessed
        :type oms_ip: str
        :param oms_username: Username used for OMS login
        :type oms_username: str
        :param oms_password: Password used for OMS login
        :type oms_password: str
        :param sysconf_path: Path to Pegasus config file defining OMS connection details
        :type sysconf_path: str
        """
        config_manager = OMSConfigManager(sysconf_path)
        config_manager.set_rnc_number(rnc_number)
        config_manager.set_oms_ip(oms_ip)
        config_manager.set_oms_credentials(oms_username, oms_password)

    def get_ipnb_parameter(self, ipnb_id, param_short_name):
        """
        Get IPNB parameter value from OMS

        :param ipnb_id: IPNB ID from OMS
        :type ipnb_id: str
        :param param_short_name: Parameter short name from OMS
        :type param_short_name: str
        :return param_value
        :rtype str
        """
        output_file_path = '/tmp/get_ipnb_parameter.txt'
        th_name = 'get_ipnb_parameter.th'
        cli_params = '-Poutput={output} -Pipnb_id={ipnb_id} -Pparam_short_name={name}'.format(output=output_file_path,
                                                                                              ipnb_id=ipnb_id,
                                                                                              name=param_short_name)
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)
        return get_file_content(output_file_path)

    def get_wbts_parameter(self, wbts_id, param_short_name):
        """
        Get WBTS parameter value from OMS

        :param wbts_id: WBTS ID from OMS
        :param param_short_name: Parameter short name from OMS
        :return param_value
        :rtype str
        """
        output_file_path = '/tmp/get_wbts_parameter.txt'
        th_name = 'get_wbts_parameter.th'
        cli_params = '-Poutput={output} -Pwbts_id={wbts_id} -Pparam_short_name={name}'.format(output=output_file_path,
                                                                                              wbts_id=wbts_id,
                                                                                              name=param_short_name)
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)
        return get_file_content(output_file_path)

    def get_wcel_parameter(self, wbts_id, wcel_id, param_short_name):
        """
        Get WCEL parameter value from OMS

        :param wbts_id: WBTS ID in which cell is located in OMS
        :type wbts_id: str
        :param wcel_id: WCEL ID from OMS
        :type wcel_id: str
        :param param_short_name: Parameter short name from OMS
        :type param_short_name: str
        :return param_value
        :rtype str
        """
        output_file_path = '/tmp/get_wcel_parameter.txt'
        th_name = 'get_wcel_parameter.th'
        cli_params = '-Poutput={output} -Pwbts_id={wbts_id} -Pwcel_id={cell_id} -Pparam_short_name={name}'.format(
            output=output_file_path, wbts_id=wbts_id, cell_id=wcel_id, name=param_short_name)
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)
        return get_file_content(output_file_path)

    def set_wbts_parameters(self, wbts_id, **params_to_change):
        """
        Set given parameters values in WBTS object in OMS

        :param wbts_id: WBTS ID from OMS
        :type wbts_id: str
        :keyword params_to_change: Parameters which should be changed in manner short_name=value (WBTSName=Shoggoth)
        """
        th_name = 'set_wbts_parameters.th'
        oms_params_to_change = self.pegasus_wrapper.build_parameters_string_for_pegasus_set_operations(params_to_change)
        cli_params = '-Pwbts_id={wbts_id} -Pparams_to_change={params}'.format(wbts_id=wbts_id,
                                                                              params=oms_params_to_change)
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)

    def set_wcel_parameters(self, wbts_id, wcel_id, **params_to_change):
        """
        Set given parameters values in WCEL object in OMS

        :param wbts_id: WBTS ID from OMS
        :type wbts_id: str
        :param wcel_id: WCEL ID from OMS
        :type wcel_id: str
        :keyword params_to_change: Parameters which should be changed in manner short_name=value (AdminPICState=0)
        """
        th_name = 'set_wcel_parameters.th'
        oms_params_to_change = self.pegasus_wrapper.build_parameters_string_for_pegasus_set_operations(params_to_change)
        cli_params = '-Pwbts_id={wbts_id} -Pwcel_id={cell_id} -Pparams_to_change={params}'.format(
            wbts_id=wbts_id, cell_id=wcel_id, params=oms_params_to_change)
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)

    def reset_wbts(self, wbts_id):
        """
        Reset given WBTS in OMS. Method ends after lauching WBTS reset. User should track reset progres on its own.

        :param wbts_id: WBTS ID from OMS
        :type wbts_id: str
        """
        th_name = 'reset_wbts.th'
        cli_params = '-Pwbts_id={wbts_id}'.format(wbts_id=wbts_id)
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)

    def get_wbts_active_alarms(self, wbts_ids):
        """
        Get active alarms from one or multiple WBTS objects in OMS.
        Long time of operation possible - depends on number of WBTS IDs.
        Default timeout value is set to 15 minutes.

        :param wbts_ids: WBTS ID from OMS. Bulk operation is supported.
                        Specify different BTS IDs separated by comma, for example: 1,2,5
        :type wbts_ids: str
        :return log_files
        :rtype list
        """
        save_filepath = '/tmp/wbts_active_alarms.txt'
        th_name = 'get_wbts_active_alarms.th'
        cli_params = '-Pwbts_id={wbts_ids} -Palarms_file_path={save_filepath}'\
            .format(wbts_ids=wbts_ids, save_filepath=save_filepath)

        files_state_before = {filename: os.stat('/tmp/%s' % filename).st_mtime for filename in os.listdir('/tmp')}
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)
        files_state_after = {filename: os.stat('/tmp/%s' % filename).st_mtime for filename in os.listdir('/tmp')}

        log_files = []
        for filename in files_state_after:
            if 'wbts_active_alarms' not in filename:
                continue
            if filename not in files_state_before:
                log_files.append('/tmp/%s' % filename)
            elif files_state_after[filename] != files_state_before[filename]:
                log_files.append('/tmp/%s' % filename)
        return log_files

    def get_wcel_active_alarms(self, wbts_ids, cell_ids="-1"):
        """
        Get active alarms from one or multiple WCEL objects in OMS.
        Long time of operation possible - depends on number of WBTS IDs and WCEL IDs.
        Default timeout value is set to 15 minutes.

        :param wbts_ids: WBTS ID from OMS. Bulk operation is supported.
                        Specify different BTS IDs separated by comma, for example: 1,2,5
        :type wbts_ids: str
        :param cell_ids: WCEL ID from OMS. Bulk operation is supported.
                        Specify different cell IDs separated by comma, for example: 1,2,5.
                        Value '-1' specifies all cell IDs.
        :type cell_ids: str
        :return log_files
        :rtype list
        """
        save_filepath = '/tmp/wcel_active_alarms.txt'
        th_name = 'get_wcel_active_alarms.th'
        cli_params = '-Pwbts_id={wbts_ids} -Pwcel_id={cell_ids} -Palarms_file_path={alarms_file_path}'\
            .format(wbts_ids=wbts_ids, alarms_file_path=save_filepath, cell_ids=cell_ids)

        files_state_before = {filename: os.stat('/tmp/%s' % filename).st_mtime for filename in os.listdir('/tmp')}
        cmd = self.pegasus_wrapper.get_cli_command(th_name, cli_params)
        self.pegasus_wrapper.execute_pegasus_cli_command(cmd)
        files_state_after = {filename: os.stat('/tmp/%s' % filename).st_mtime for filename in os.listdir('/tmp')}

        log_files = []
        for filename in files_state_after:
            if 'wcel_active_alarms' not in filename:
                continue
            if filename not in files_state_before:
                log_files.append('/tmp/%s' % filename)
            elif files_state_after[filename] != files_state_before[filename]:
                log_files.append('/tmp/%s' % filename)
        return log_files
